class Solution {
public:
    vector<int> findRightInterval(vector<vector<int>>& intervals) {
        int n = (int)intervals.size();
        vector<pair<int,int>> starts; // (start, original index)
        starts.reserve(n);
        for (int i = 0; i < n; i++) {
            starts.push_back({intervals[i][0], i});
        }
        sort(starts.begin(), starts.end());
        vector<int> ans(n);
        for (int i = 0; i < n; i++) {
            int target = intervals[i][1];
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (starts[mid].first >= target) hi = mid;
                else lo = mid + 1;
            }
            ans[i] = (lo < n) ? starts[lo].second : -1;
        }
        return ans;
    }
};
